// Add to js/main.min.js
function populateVoucherDropdown() {
    if (typeof getSavedVouchers !== 'function') {
        console.error('getSavedVouchers function is not defined. Ensure voucherManager.js is loaded.');
        return;
    }
    const vouchers = getSavedVouchers();
    const selectElement = document.getElementById('savedVouchersSelect');

    // Ensure form elements are correctly referenced (document.login might not be available if script runs too early)
    const loginForm = document.forms.login;
    if (!loginForm) {
        console.error("Login form not found.");
        return;
    }
    const usernameField = loginForm.username;
    const speedSelect = loginForm.speed;

    if (!selectElement || !usernameField || !speedSelect) {
        console.error('Required elements for voucher dropdown (select, username input, speed select) are missing from the DOM or form.');
        return;
    }

    // Clear existing options (except the placeholder)
    while (selectElement.options.length > 1) {
        selectElement.remove(1);
    }

    if (vouchers.length === 0) {
        selectElement.options[0].text = 'لا توجد كروت محفوظة';
        selectElement.disabled = true; // Disable select if no vouchers
    } else {
        selectElement.options[0].text = 'اختر كرت محفوظ...';
        selectElement.disabled = false; // Enable select
        vouchers.forEach(voucher => {
            const option = document.createElement('option');
            let speedName = voucher.speed;
            // Attempt to find the display name for the speed value
            if (speedSelect && speedSelect.options) { // ADDED GUARD
                for(let i=0; i < speedSelect.options.length; i++) {
                    if(speedSelect.options[i].value === voucher.speed) {
                        speedName = speedSelect.options[i].text;
                        break;
                    }
                }
            }
            option.textContent = `${voucher.username} (${speedName})`;
            option.value = voucher.username;
            selectElement.appendChild(option);
        });
    }
}

