document.addEventListener("DOMContentLoaded", function() {
    // Check for pending speed change from change_speed.html
    try {
        const pendingChangeJson = localStorage.getItem('pendingSpeedChange');
        if (pendingChangeJson) {
            const pendingChange = JSON.parse(pendingChangeJson);
            // Optional: Check timestamp if you want to expire old pending changes
            // const MAX_PENDING_CHANGE_AGE = 5 * 60 * 1000; // 5 minutes
            // if (new Date().getTime() - pendingChange.timestamp < MAX_PENDING_CHANGE_AGE) {

            const loginForm = document.forms.login; // Use document.forms.login for robustness
            if (loginForm && loginForm.username && loginForm.speed) {
                loginForm.username.value = pendingChange.username;
                loginForm.speed.value = pendingChange.newSpeed;

                // Populate voucher dropdown to see if this card is there, and select it if so.
                if (typeof populateVoucherDropdown === 'function') {
                    populateVoucherDropdown();
                    const VouchersSelect = document.getElementById('savedVouchersSelect');
                    if (VouchersSelect) VouchersSelect.value = pendingChange.username;
                }

                // Trigger change on speed select for UI updates (e.g. speedStatus)
                if (document.createEvent) {
                    var event = document.createEvent('HTMLEvents');
                    event.initEvent('change', true, false);
                    loginForm.speed.dispatchEvent(event);
                } else { // Older IE
                    loginForm.speed.fireEvent('onchange');
                }

                console.log('Applied pending speed change for user:', pendingChange.username);
            }
            // } else {
            //    console.log('Stale pending speed change ignored.');
            // }
            localStorage.removeItem('pendingSpeedChange'); // Clear it after attempting to apply
        }
    } catch (e) {
        console.error('Error processing pending speed change:', e);
        localStorage.removeItem('pendingSpeedChange'); // Clear it also on error
    }

    // Function to parse URL parameters (if not already globally available or in a utility script)
    function getUrlParameter(name) { // Ensure this function is available or define it
        name = name.replace(/[\[]/, '\[').replace(/[\]]/, '\]');
        const regex = new RegExp('[\?&]' + name + '=([^&#]*)');
        const results = regex.exec(location.search);
        return results === null ? '' : decodeURIComponent(results[1].replace(/\+/g, ' '));
    }

    const selectedSpeedFromPlans = getUrlParameter('speed_value');
    if (selectedSpeedFromPlans) {
        const loginForm = document.forms.login; // Use document.forms.login
        if (loginForm && loginForm.speed) {
            const speedDropdown = loginForm.speed;
            // Check if the speed_value from URL exists as an option
            let optionExists = false;
            for (let i = 0; i < speedDropdown.options.length; i++) {
                if (speedDropdown.options[i].value === selectedSpeedFromPlans) {
                    optionExists = true;
                    break;
                }
            }

            if (optionExists) {
                speedDropdown.value = selectedSpeedFromPlans;
                console.log('Pre-selected speed from plans.html:', selectedSpeedFromPlans);

                // Trigger change on speed select for UI updates (e.g. speedStatus)
                if (document.createEvent) {
                    var event = document.createEvent('HTMLEvents');
                    event.initEvent('change', true, false);
                    speedDropdown.dispatchEvent(event);
                } else { // Older IE
                    speedDropdown.fireEvent('onchange');
                }
            } else {
                console.warn(`Speed value "${selectedSpeedFromPlans}" from URL not found in dropdown options.`);
            }
        }
        // Clean the URL parameter
        if (history.replaceState) {
            const cleanUrl = window.location.protocol + "//" + window.location.host + window.location.pathname;
            history.replaceState({ path: cleanUrl }, '', cleanUrl);
        }
    }

    $errorContainer.addEventListener("click", hideErrorPopup);
    var a = document.querySelectorAll("button[parent-id]"),
        b;
    for (b in a) {
        var c = a[b];
        if ("object" == typeof c) {
            var d = a[b].getAttribute("parent-id");
            d = document.getElementById(d);
            if (null == d) return;
            initHotspotEvents(c, d)
        }
    }
    document.login.addEventListener("submit", function(e) {
        animating || onLoginSubmitted();
        e.preventDefault()
    });
    setTimeout(function() { return getRequest("/login?var=callBack") }, 50);

    // Init for voucher dropdown (populate, and set up listeners)
    if (typeof populateVoucherDropdown === 'function') {
        populateVoucherDropdown();
    } else {
        console.error('populateVoucherDropdown is not defined. Cannot populate voucher list on load.');
    }

    const savedVouchersSelectElement = document.getElementById('savedVouchersSelect');
    if (savedVouchersSelectElement) {
        savedVouchersSelectElement.addEventListener('change', function() {
            const selectedUsername = this.value;
            const loginForm = document.forms.login;
            if (!loginForm) return;

            if (selectedUsername && typeof getSavedVouchers === 'function') {
                const vouchers = getSavedVouchers();
                const selectedVoucher = vouchers.find(v => v.username === selectedUsername);
                if (selectedVoucher) {
                    loginForm.username.value = selectedVoucher.username;
                    loginForm.speed.value = selectedVoucher.speed;

                    // Trigger change on speed select for compatibility with existing scripts (e.g. speedStatus update)
                    if (document.createEvent) { // Modern browsers
                        var event = document.createEvent('HTMLEvents');
                        event.initEvent('change', true, false);
                        loginForm.speed.dispatchEvent(event);
                    } else { // Older IE
                        loginForm.speed.fireEvent('onchange');
                    }
                }
            } else if (!selectedUsername) {
                loginForm.username.value = '';
                // Optionally reset speed too, or leave it as is
            }
        });
    }

    const navigateToChangeSpeedButton = document.getElementById('navigateToChangeSpeed');
    if (navigateToChangeSpeedButton) {
        navigateToChangeSpeedButton.addEventListener('click', function() {
            let actualUsername = window.currentLoggedInUsername;

            const speedSelectElement = document.forms.login.speed;
            let currentSpeedValue = '';
            if (speedSelectElement) {
                 currentSpeedValue = speedSelectElement.value;
            }
            // Fallback for currentSpeedValue if not found on login form's select (e.g. if form is hidden)
            if (!currentSpeedValue && typeof $loginData !== 'undefined' && $loginData.profile) {
                 // This is a guess, depends on what $loginData might contain from status
                 // The speed value (like 55987b0d-...) is needed, not the profile name.
                 // This part remains tricky if the main speed select isn't the source of truth.
                 // For now, we rely on speedSelectElement.value.
            }


            if (!actualUsername) {
                 // If window.currentLoggedInUsername wasn't set, try a last resort.
                 // This is less reliable and ideally should not be needed.
                const vouchers = typeof getSavedVouchers === 'function' ? getSavedVouchers() : [];
                if (vouchers.length > 0 && typeof $loginData !== 'undefined' && vouchers[0].username === $loginData.username) {
                    actualUsername = vouchers[0].username;
                } else {
                    alert("لم يتم تحديد اسم المستخدم الحالي. لا يمكن تغيير السرعة.");
                    return;
                }
            }

            let logoutLink = 'logout.html'; // Default
            if (typeof $loginData !== 'undefined' && $loginData.link_logout) {
                logoutLink = $loginData.link_logout;
            }

            if (actualUsername && currentSpeedValue) {
                window.location.href = `change_speed.html?username=${encodeURIComponent(actualUsername)}&speed_value=${encodeURIComponent(currentSpeedValue)}&logout_url=${encodeURIComponent(logoutLink)}`;
            } else {
                alert('لا يمكن تحديد المستخدم الحالي أو السرعة. لا يمكن المتابعة.');
            }
        });
    }

    const deleteVoucherButtonElement = document.getElementById('deleteVoucherButton');
    if (deleteVoucherButtonElement) {
        deleteVoucherButtonElement.addEventListener('click', function() {
            const selectElement = document.getElementById('savedVouchersSelect');
            const selectedUsername = selectElement.value;
            const loginForm = document.forms.login;
            if (!loginForm) return;

            if (selectedUsername && typeof deleteVoucher === 'function') {
                if (!confirm(`هل أنت متأكد أنك تريد حذف الكرت ${selectedUsername}؟`)) {
                    return;
                }
                deleteVoucher(selectedUsername);
                populateVoucherDropdown();

                // If the deleted voucher was the one displayed in the username field, clear the field
                if (loginForm.username.value === selectedUsername) {
                    loginForm.username.value = '';
                    selectElement.value = ""; // Reset dropdown to placeholder
                }
            } else if (!selectedUsername) {
                if(typeof Swal === 'function') {
                    Swal.fire('خطأ', 'يرجى اختيار كرت محفوظ لحذفه.', 'error');
                } else {
                    alert('يرجى اختيار كرت محفوظ لحذفه.');
                }
            } else {
                console.error('deleteVoucher function is not defined.');
            }
        });
    }
}, !1);